vec2 v0 = b - a;
vec2 v1 = c - a;
vec2 v2 = p - a;

double d00 = v0 * v0;
double d01 = v0 * v1;
double d11 = v1 * v1;
double d20 = v2 * v0;
double d21 = v2 * v1;

double denom = d00 * d11 - d01 * d01;
double v = (d11 * d20 - d01 * d21) / denom;
double w = (d00 * d21 - d01 * d20) / denom;
double u = 1.0 - v - w;

return {u, v, w};

